"""Publish a compact bounded audit only after frozen-run and semantic checks pass."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,argparse
W=Path(__file__).resolve().parent
def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def binding(p,count=None):return {'path':str(p),'sha256':sha(p),**({'case_count':count} if count is not None else {})}
ap=argparse.ArgumentParser();ap.add_argument('--run',required=True);a=ap.parse_args();D=Path(a.run).resolve();summary=read(D/'summary.json');digest=summary['script_sha256'];short=digest[:12]
integrityp=W/('run-integrity-'+short+'.json');integrity=read(integrityp)
assert integrity['counts']['failed']==0
assert integrity['summary_sha256']==sha(D/'summary.json') and integrity['ranker_script_sha256']==digest
probep=W/('probe-results-'+short+'.json');p=read(probep);extra=W/('supplemental-probes-'+short+'.json');e=read(extra)
assert p['ranker_script_sha256']==e['script_sha256']==digest
r={x['id']:x for x in p['results']};assert len(r)==13
assert r['formula-not-sample']['cue_window']['sample_tokens']==[]
assert r['figure-label-not-sample']['cue_window']['sample_tokens']==[]
assert r['explicit-sample-positive']['cue_window']['sample_tokens']==['S1'] and r['explicit-sample-positive']['links']
assert not r['different-samples-unlinked']['links'] and not r['different-samples-unlinked']['priority_band'].startswith('A_')
for key in ['reference-coordinates','theory-coordinates','precursor-crystal','ambiguous-article-cooccurrence']:assert r[key]['priority_band'].startswith('E_') and r[key]['cue_window']['origin_warnings']
assert 'fixed_or_constrained_positions' in r['fixed-minority']['cue_window']['origin_warnings'] and not r['fixed-minority']['priority_band'].startswith('A_')
assert not r['negated-monodisperse']['links'] and not any('monodispers' in k.lower() for k in r['negated-monodisperse']['cue_window'])
assert 'negated_or_prior_work_structure' in r['absence-of-refinement']['cue_window']['origin_warnings'] and not r['absence-of-refinement']['priority_band'].startswith('A_')
assert r['size-only-positive']['priority_band'].startswith('D_') and r['size-only-positive']['links']
assert not r['borrowed-procedure']['cue_window']['recipe_candidate']
assert all(x['verified_pair'] is False and x['task_ready'] is False for x in r.values())
assert e['counts']=={'checks':4,'failed':0}
scope=read(W/'current-scope-recheck.json');holds=read(W/'generation-dispatch-holds.json');assert scope['fixed_scope_sets_match'] and scope['generation_reopen_holds_same'] and len(holds['groups'])==4
now=datetime.now(timezone.utc).isoformat()
report={'schema':'mattersyn-independent-pair-ranker-audit/1','passed':True,'status':'passed_for_offline_candidate_screen_only','checked_at':now,'reviewer':'/root/all_page_coverage','ranker_script_sha256':digest,'summary_sha256':sha(D/'summary.json'),'summary_path':str(D/'summary.json'),'semantic_probe_bindings':[binding(probep,13),binding(extra,4)],'semantic_expected_cases_binding':binding(W/'independent-probe-cases.json',13),'integrity_report_path':str(integrityp),'integrity_report_sha256':sha(integrityp),'current_partition_sha256':scope['current_partition_sha256'],'frozen_partition_sha256':scope['frozen_partition_sha256'],'scope_recheck_binding':binding(W/'current-scope-recheck.json'),'generation_dispatch_holds_path':str(W/'generation-dispatch-holds.json'),'generation_dispatch_holds_sha256':sha(W/'generation-dispatch-holds.json'),'counts':integrity['counts']|{'semantic_cases':17,'known_source_file_blocks':32,'known_source_group_holds':32,'generation_dispatch_holds':4},'source_benchmark_pass_required_separately':True,'scope_of_pass':['Exact fixed-cutoff scope and canonicalized file denominator; original holds/status labels retained.','Frozen input/output hashes and selected current cache-text byte replays; all selected cue references resolve.','Known promotion, wrong intended identity and misassigned source-role blocks retain separate unresolved identities.','Bounded semantic negatives, sample-link guards and atomic-versus-reflection/table tests passed.','No automatic verified-pair, training-ready or exclusion transitions are asserted.'],'resolved_findings':[{'id':'RANK-AUDIT-01','issue':'Figure/table labels could become sample IDs.','resolution':'Figure/table/section/equation labels are removed from specimen-token matching.'},{'id':'RANK-AUDIT-02','issue':'S1 synthesis and S2 structure in one window could self-link.','resolution':'Recipe and structure sentence tokens are separated; different explicit specimen IDs do not link.'},{'id':'RANK-AUDIT-03','issue':'Four already-authorized aliases could drop legacy file copies.','resolution':'Frozen authoritative alias map preserves all13831fixed file dispositions under9532canonical scopes.'},{'id':'RANK-AUDIT-04','issue':'S4-1 and S4-2 could collapse to parent S4.','resolution':'Hyphenated variant tokens remain distinct.'},{'id':'RANK-AUDIT-05','issue':'Top atomic band could be based on coordinate mentions/deposit only.','resolution':'A nomination requires present numeric atom-table cues, measurement/refinement and explicit local linkage; still not independently verified A.'},{'id':'RANK-AUDIT-06','issue':'Prior-work/negated structure cues and one-operation quantified recipes were mishandled.','resolution':'Prior/negative context retained; quantitative explicit short preparations remain candidates.'},{'id':'RANK-AUDIT-07','issue':'Raw overlapping cue text would lie outside the normal private exclusion.','resolution':'Final source cue corpus is under private/; root additionally excludes all source-cues.jsonl paths.'}],'nonblocking_limits':['This pass does not measure whole-corpus precision or recall and is not full scientific source review. The separately required actual-source benchmark audit covers selected known table/CIF cases.','Historical source hash/cache path/character-count binding and new text hashes do not authenticate old text contents cryptographically against original PDFs; current original bytes were not all rehashed.','Mixed phases/components, fixed/refined positions, exact targets and physical batches still require source-specific review. A/B/C/D names are nominations, not verified rubric classifications.','All source holds and four generation dispatch holds must be enforced before activation/dispatch. Partition generation is not proof that current main/SI membership and audit coverage are complete.','Manual-format/text holds, image-only pages, unknown roles/pairing, missing SI and any low score remain explicit unresolved work; none is a scientific exclusion.','Zero automated verified pairs does not invalidate existing independently audited source packages or previously verified/published contributions.','Candidate source identity remains unassessed when absent from the known-exception overlay.'],'scientific_pair_approvals_added':0,'training_approvals_added':0,'exclusions_added':0,'shared_ledger_or_canonical_state_modified':False}
(W/'independent-audit.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
(W/'independent-audit.md').write_text(f'''# Independent bounded ranker audit\n\nPassed for the offline candidate screen only. Script `{digest}` and exact completed summary are bound in `independent-audit.json`.\n\nThe audit checked {integrity['counts']['scope_count']:,} canonical scopes and {integrity['counts']['file_count']:,} source-file dispositions,17 semantic regression cases, the32 known source holds, four generation dispatch holds and selected cache hashes. All independent integrity checks passed. Three nested files remain separately identity-held.\n\nThis is not a whole-corpus scientific audit, a precision/recall estimate, a verified pair count, training admission or exclusion approval. The separate actual-source benchmark pass is still required. Historical cache binding does not prove cryptographic equality to old extracted text or current original PDF bytes. Mixed phases and source/sample links require independent source review.\n\nBefore activation or dispatch, enforce source/role holds and `generation-dispatch-holds.json`; preserve active claims, prior audits and source states. Missing overlay entries remain unassessed. No shared source, ledger, canonical, website or training data was edited by this audit.\n''',encoding='utf8')
names=['independent-audit.json','independent-audit.md','independent-probe-cases.json',probep.name,extra.name,integrityp.name,'generation-dispatch-holds.json','current-scope-recheck.json','run_independent_probes.py','run_supplemental_probes.py','audit_frozen_run.py','finalize_independent_audit.py']
freeze={'status':'frozen_bounded_independent_audit','passed':True,'ranker_script_sha256':digest,'summary_sha256':sha(D/'summary.json'),'created_at':now,'files':[binding(W/n) for n in names]};(W/'audit-freeze-v1.json').write_text(json.dumps(freeze,indent=2)+'\n',encoding='utf8')
(W/'checkpoint.json').write_text(json.dumps({'status':'bounded_independent_audit_passed','at':now,'ranker_script_sha256':digest,'summary_sha256':sha(D/'summary.json'),'audit_sha256':sha(W/'independent-audit.json'),'source_benchmark_gate':'required separately','next':'Root may evaluate safe priority activation only with separate source-benchmark pass, fresh scope binding and all source/generation holds; no automatic pair/training/exclusion transitions.'},indent=2)+'\n',encoding='utf8')
print(json.dumps({'passed':True,'audit_sha256':sha(W/'independent-audit.json'),'freeze_sha256':sha(W/'audit-freeze-v1.json'),'summary_sha256':sha(D/'summary.json'),'script_sha256':digest,'counts':report['counts']},indent=2))
